        "new_string": "def require(roles, permission):\n    \"\"\"Gate an endpoint: raises PermissionDenied instead of returning False.\"\"\"\n    if not has_permission(roles, permission):\n        raise PermissionDenied(permission)\n\n\nclass RoleGraph:\n    \"\"\"Hierarchical roles with deny-overrides, for the next-generation checks.\n\n    Roles are declared with add_role() in definition order: a role may only\n    inherit from roles that already exist. A role's effective permissions\n    are its own grants plus everything inherited through its parents\n    (transitively; diamonds are fine), minus any permission denied anywhere\n    in that closure. Denies win, the way Windows ACLs do: a deny overrides\n    grants from other branches of the closure and cannot be re-granted\n    further down the tree.\n    \"\"\"\n\n    def __init__(self):\n        # Per role, the full closure of grants and denies reachable through\n        # inheritance, own contributions included. Parents are merged when\n        # a role is declared, so these are already transitive and the graph\n        # can never grow a cycle.\n        self._closure_grants = {}\n        self._closure_denies = {}\n\n    def add_role(self, name, grants=(), denies=(), inherits=()):\n        \"\"\"Declare a role. Unknown parents raise KeyError; redefining a\n        role or using a blank name raises ValueError.\"\"\"\n        if not name or not name.strip():\n            raise ValueError(\"role name must not be blank\")\n        if name in self._closure_grants:\n            raise ValueError(\"role already defined: %s\" % name)\n        parents = list(inherits)\n        for parent in parents:\n            if parent not in self._closure_grants:\n                raise KeyError(parent)\n        closure_grants = set(grants)\n        closure_denies = set(denies)\n        for parent in parents:\n            closure_grants |= self._closure_grants[parent]\n            closure_denies |= self._closure_denies[parent]\n        self._closure_grants[name] = frozenset(closure_grants)\n        self._closure_denies[name] = frozenset(closure_denies)\n\n    def _closure(self, role):\n        \"\"\"(grants, denies) closure of one role; unknown roles KeyError.\"\"\"\n        return self._closure_grants[role], self._closure_denies[role]\n\n    def effective_grants(self, role):\n        \"\"\"Net permissions a single role carries; unknown roles KeyError.\"\"\"\n        grants, denies = self._closure(role)\n        return grants - denies\n\n    def allowed(self, roles, permission):\n        \"\"\"True when any of the roles grants the permission and nothing in\n        their combined closures denies it. An empty role list allows\n        nothing; unknown roles are a KeyError.\"\"\"\n        granted = set()\n        denied = set()\n        for role in roles:\n            role_grants, role_denies = self._closure(role)\n            granted |= role_grants\n            denied |= role_denies\n        return permission in granted and permission not in denied\n\n    def require(self, roles, permission):\n        \"\"\"Graph counterpart of the flat require() gate.\"\"\"\n        if not self.allowed(roles, permission):\n            raise PermissionDenied(permission)"
